contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint _minSum, address _log) public {
        c.Initialized(); if (__ESBMC_reverted()) return;

        bool setMinSumReverted;
        c.SetMinSum(_minSum); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            setMinSumReverted = true;
        } else {
            setMinSumReverted = false;
        }

        bool setLogFileReverted;
        c.SetLogFile(_log); bool __rev1 = __ESBMC_reverted(); if (__rev1) {
            setLogFileReverted = true;
        } else {
            setLogFileReverted = false;
        }

        assert(setMinSumReverted && setLogFileReverted);
    }
    receive() external payable {}
}

