// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 _minSum, address _log) internal {
        try c.Initialized() {} catch { return; }
        bool setMinSumReverted;
        try c.SetMinSum(_minSum) {
            setMinSumReverted = false;
        } catch {
            setMinSumReverted = true;
        }
        bool setLogFileReverted;
        try c.SetLogFile(_log) {
            setLogFileReverted = false;
        } catch {
            setLogFileReverted = true;
        }
        assertTrue(setMinSumReverted && setLogFileReverted);
    }

    function testFuzz_run(uint256 _minSum, address _log) public {
        vm.assume(_log.code.length == 0 && uint160(_log) > 0xffff && _log != address(this) && _log != address(c) && _log != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && _log != 0x000000000000000000636F6e736F6c652e6c6f67 && _log != 0x4e59b44847b379578588920cA78FbF26c0B4956C && _log != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(_minSum, _log);
    }

    receive() external payable {}
}
